import figma from "figma";

const instance = figma.selectedInstance;

const attr = (name, value) => {
  if (value === undefined || value === false) return "";
  if (value === true) return ` ${name}`;
  if (typeof value === "number") return ` ${name}={${value}}`;
  return value.startsWith("{") ? ` ${name}=${value}` : ` ${name}="${value}"`;
};
const textOf = (node) =>
  node && node.type === "TEXT" ? node.textContent : undefined;
const numberOf = (text) => Number((String(text).match(/\d+/g) ?? []).pop());

const label = instance.getString("Label");
const hideInput = instance.getBoolean("Show input", {
  true: undefined,
  false: true,
});
const disabled = instance.getEnum("State", {
  Default: undefined,
  Disabled: true,
});
const value = numberOf(
  textOf(instance.findLayers((node) => node.name === "Value")[0]),
);
const value2 = numberOf(
  textOf(instance.findLayers((node) => node.name === "Value")[1]),
);

export default {
  id: "Slider",
  example: instance.getEnum("Mode", {
    single: figma.code`<HvSlider${attr("label", label)}${attr("hideInput", hideInput)}${attr("disabled", disabled)} defaultValues={[${value ?? ""}]} />`,
    range: figma.code`<HvSlider${attr("label", label)}${attr("hideInput", hideInput)}${attr("disabled", disabled)} defaultValues={[${value ?? ""}, ${value2 ?? ""}]} />`,
  }),
  imports: ['import { HvSlider } from "@pentaho/uikit-react-core";'],
  metadata: { nestable: true },
};
